#!/usr/bin/env python3
"""Write docs/STATS.md (auto-generated) from symbols/N3DS_SYMBOL_TABLE.csv and the per-component CSVs."""
import csv, collections, glob, os
R = os.path.abspath(os.path.dirname(__file__) + '/..')
rows = list(csv.DictReader(open(R + '/symbols/N3DS_SYMBOL_TABLE.csv')))
levels = ['exact', 'adapted_n3ds', 'probable_by_transfer', 'probable_by_callgraph', 'probable_by_layout', 'probable_by_table', 'probable_by_similarity', 'probable_by_constants', 'probable_by_gap_function', 'derived_structural', 'derived_decompiled', 'manual_decompiled', 'unresolved']
c = collections.defaultdict(collections.Counter)
for r in rows: c[r['component']][r['confidence_level']] += 1
out = ['# Automatic statistics (generated by tools/make_stats.py)\n', '| Component | rows | ' + ' | '.join(l.replace('_', ' ') for l in levels) + ' |', '|---|---:|' + '---:|' * len(levels)]
tot = collections.Counter()
for k in sorted(c):
    v = c[k]; tot.update(v)
    out.append(f'| {k} | {sum(v.values())} | ' + ' | '.join(str(v[l]) if v[l] else '' for l in levels) + ' |')
out.append(f'| **TOTAL** | {sum(tot.values())} | ' + ' | '.join(str(tot[l]) for l in levels) + ' |')
# match_basis under adapted
mb = collections.Counter(r['match_basis'] for r in rows if r['confidence_level'] == 'adapted_n3ds')
out += ['', '`adapted_n3ds` rows by underlying match level: ' + ', '.join(f'{k}={v}' for k, v in mb.most_common()), '']
ver = collections.Counter()
for f in glob.glob(R + '/symbols/*.csv'):
    if os.path.basename(f).startswith('N3DS_'): continue
    for r in csv.DictReader(open(f)):
        if r.get('verification') and r['confidence_level'] != 'unresolved' and r['confidence_level'] != 'exact':
            ver[r['verification'].split(';')[0]] += 1
out += ['Verification status of every non-exact matched row (call-site / string / caller agreement, see METHODOLOGY): ' + ', '.join(f'{k}={v}' for k, v in ver.most_common()), '']
open(R + '/docs/STATS.md', 'w').write('\n'.join(out) + '\n'); print('\n'.join(out))
